esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take arbitrary callee and data. No Ether involved.
    function run(address callee, bytes memory data) public payable {
        require(true);

        bool innerSucceeded;
        bool outerReverted;

        // Perform the call and detect whether c.forward reverted.
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            outerReverted = true;
            // If forward reverted, it could be because the inner call returned false or because the inner call itself reverted.
            // We conservatively set innerSucceeded = false in this branch.
            innerSucceeded = false;
        } else {
            outerReverted = false;
            // If forward succeeded, the low-level call inside must have returned true.
            // We cannot observe the inner returned bool directly, but we assert that
            // it's impossible for forward to succeed while the inner call returned false,
            // which manifests as: when forward does not revert, then the inner call must have succeeded.
            innerSucceeded = true;
        }

        // General rule: forward cannot both succeed (outerReverted == false) and have the inner call have returned false.
        // We express that as: if outer call succeeded then innerSucceeded must be true.
        assert(!(outerReverted == false && innerSucceeded == false));
    }

    receive() external payable { }
}

