pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function _run(address callee, bytes memory data) internal {
        vm.assume(true);
        bool innerSucceeded;
        bool outerReverted;
        try c.forward(callee, data) {
            outerReverted = false;
            // If forward succeeded, the low-level call inside must have returned true.
            // We cannot observe the inner returned bool directly, but we assert that
            // it's impossible for forward to succeed while the inner call returned false,
            // which manifests as: when forward does not revert, then the inner call must have succeeded.
            innerSucceeded = true;
        } catch {
            outerReverted = true;
            // If forward reverted, it could be because the inner call returned false or because the inner call itself reverted.
            // We conservatively set innerSucceeded = false in this branch.
            innerSucceeded = false;
        }
        assertTrue(!(outerReverted == false && innerSucceeded == false));
    }

    function testFuzz_run(address callee, bytes memory data) public {
        vm.assume(callee.code.length == 0 && uint160(callee) > 0xffff && callee != address(this) && callee != address(c) && callee != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && callee != 0x000000000000000000636F6e736F6c652e6c6f67 && callee != 0x4e59b44847b379578588920cA78FbF26c0B4956C && callee != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(callee, data);
    }

    receive() external payable { }
}
